// In APPEND mode every write goes to the end of the stream, whatever fseek() did.
// Measured across the backends elephc implements separately.
function t(string $label, string $target, string $mode): void {
    $fp = fopen($target, $mode);
    fwrite($fp, "hello");
    fseek($fp, 0, SEEK_SET);
    $tellAfterSeek = ftell($fp);
    fwrite($fp, "world");
    $tellAfterWrite = ftell($fp);
    printf("%-26s %-22s seek=%d write=%d %s\n",
        $label, var_export(stream_get_contents($fp, -1, 0), true),
        $tellAfterSeek, $tellAfterWrite, $mode);
    fclose($fp);
}

